API Gateway / Backend-for-Frontend (BFF).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway_bff, "API Gateway / Backend-for-Frontend (BFF)") {
    Component(api_router_and_gateway, "API Router and Gateway", "Azure Container Apps (Node.js/Go)", "Handles incoming client requests, request routing, and reverse proxying to downstream services.")
    Component(authentication_and_token_translation, "Authentication & Token Translation", "Azure Container Apps (Node.js/Go)", "Validates incoming tokens from the Enterprise Identity Provider and translates them for backend services.")
    Component(response_cache, "Response Cache", "Azure Container Apps (Node.js/Go)", "Provides caching layers to improve performance and reduce latency for frequent client requests.")
}

Rel(api_router_and_gateway, authentication_and_token_translation, "Validates security tokens for requests")
Rel(api_router_and_gateway, response_cache, "Retrieves and stores cached responses")
@enduml

Azure SQL Database.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(azure_sql_database, "Azure SQL Database") {
    Component(Claims Relational Tables, "Claims Relational Tables", "Azure SQL Database Tables", "Stores core claims data, policies, and participant details relational structures.")
    Component(Azure SQL Ledger Tables, "Azure SQL Ledger Tables", "Azure SQL Ledger", "Provides tamper-evident auditing and cryptographic verification for claims transactions.")
    Component(Change Tracking Engine, "Change Tracking Engine", "Azure SQL Change Tracking", "Monitors and records data modifications to support incremental synchronization with the Data Sync Engine.")
}

Rel(Claims Relational Tables, Azure SQL Ledger Tables, "Records immutable history of data modifications")
Rel(Claims Relational Tables, Change Tracking Engine, "Exposes changed rows for synchronization")

@enduml
